@startuml

class User {
  + name
  + surname
}

class Subscriber extends User {
}

class Card {
  + credit
}

class Movie {
  + title
}

class Order {
  + date
}

class MovieShop {
  + browseCatalogue()
  + orderMovie()
  + subscribe()
}

User "1" -- "*" Order : places
Subscriber "1" -- "1" Card : uses
Subscriber "1" -- "*" Order : places
MovieShop "1" -- "*" Movie : contains
MovieShop "1" -- "*" Order : handles
Order "*" -- "1" Movie : includes

@enduml

